ar": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='engineered-medical-systems' AND approved AND profile IS NULL;
UPDATE companies SET description='Equipment Solutions Inc. (ESI) was established in 1997 in Sterling, Virginia.

The company operates as a manufacturer''s representative and distributor of foodservice equipment, smallwares, and tabletop products, partnering with national and international brands. It also collaborates with its sister company, Hospitality Solutions Group, to supply indoor and outdoor furniture and shade solutions.

ESI serves foodservice professionals across Washington, DC, Maryland, and Virginia.

The company emphasizes knowledgeable guidance, responsive service, and a hands-on approach that lets clients test equipment in its demo kitchen before purchasing. It positions itself as a single source for equipment, smallwares, furniture, and shade, backed by decades of industry experience.', certifications=ARRAY['HACCP']::text[], profile='{"capabilities": ["Foodservice equipment distribution", "Smallwares and tabletop supply", "Indoor and outdoor furniture supply", "Shade solutions supply", "Test kitchen demonstrations", "Product testing and evaluation", "Training sessions", "Project consulting", "Design collaboration", "Manufacturer representation"], "industries": ["Foodservice", "Restaurant", "Hospitality"], "materials": [], "equipment": ["BigRig\u2122 family", "Varikw", "Migali Industries under-counter refrigerators", "Frosty Factory machines"], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Founded in 1997 -> db", "Headquartered in Sterling, Virginia -> db", "John Coates is a principal and has been in manufacturer''s representative business since 1997 -> /about", "Company operates a showroom, test kitchen, demo space, training facility, and warehouse in Loudoun Commerce Center -> /about", "Facility is five miles from Dulles Airport and Reston Town Center -> /about", "Serves foodservice professionals in Washington, DC, Maryland, and Virginia -> /about", "Customers include manufacturers, designers, consultants, franchise organizations, educational institutions, and independent operators -> /about", "Partners with Hospitality Solutions Group for furniture and shade solutions -> /", "Offers foodservice equipment, smallwares, and tabletop products from industry-leading manufacturers -> /", "Certification: HACCP -> db", "Team members: John Coates, Bruce Hicks, Greg Horn, Eric Bartunek, Tina Jordan, Kaitlyn -> /about", "Brands carried: BigRig\u2122, Varikw, Migali Industries, Frosty Factory -> /"], "company_type": null, "makes_produc