UPDATE companies SET description='Founded in 2000 in Minneapolis, Minnesota, Flexible Circuit Technologies (FCT) operates as a global supplier of flexible circuit solutions. The company maintains its headquarters in Minneapolis while running a 485,000-square-foot manufacturing facility in Zhuhai, China.

FCT designs and manufactures single-, double-, and multilayer flexible circuits, rigid-flex circuits, flexible heaters, flat-flex cables, printed electronics, and medical catheter circuits. The company provides full-service electronic manufacturing services (EMS) including surface-mount and through-hole assembly, connector and wire assembly with epoxy coating, plastic molding, sub-assembly, and complete box builds. Its Zhuhai facility produces high-density PCBs, FPCs, rigid-flex, substrate-like PCBs (SLPs), and flexible heaters, supporting both low-mix/high-volume and high-mix/low-volume programs from prototype through production.

The company serves automotive, medical, wearable, industrial, consumer electronics, telecom/data, contract manufacturers, EMS providers, and product development labs. In automotive, FCT supplies EV battery monitoring solutions for vehicles ranging from transit to power tools. Medical customers use its flexible circuits in catheters, connected monitoring devices, and surgical tools. Wearable and consumer electronics programs leverage the firm''s design expertise for miniaturized, high-reliability interconnects.

FCT differentiates itself through a hybrid model that pairs U.S.- and Asia-based application engineers and CAD teams—led by engineers with over 25 years of flexible-circuit experience—with Asia-based production. Director of Application Engineering Mark Finstad holds leadership roles in IPC flexible-circuit standards committees, giving the company direct influence on industry specifications. The firm emphasizes design-for-manufacturing consultation, supply-chain management, inventory stocking for just-in-time delivery, and comprehensive testing services.', certifications=ARRAY['IATF16949']::text[], profile='{"capabilities": ["Flexible circuit design (single, double, multilayer)", "Rigid-flex circuit design", "Flexible heater design", "Printed electronics design", "Medical catheter flexible circuit design", "Flat flex cable (FFC) manufacturing", "Surface mount technology (SMT) assembly", "Through-hole assembly", "Connector assembly", "Wire assembly with epoxy coating", "Plastic molding", "Sub-assembly integration", "Complete product box build", "Electrical testing", "Functional testing", "Hardware testing", "Software testing", "Custom test equipment development", "Design for manufacturing (DFM) consultation", "Supply chain management", "Prototyping", "Program management", "Inventory stocking / JIT delivery", "Rapid prototyping"], "industries": ["Automotive", "Medical", "Wearable", "Industrial", "Consumer Products", "Telecom/Data", "Contract Manufacturers (CMs)", "Electronic Manufacturing Services (EMS)", "Product Development/Engineering Labs"], "materials": [], "equipment": [], "volume": "Prototype to high volume; low-mix/high-volume and high-mix/low-volume programs", "lead_time": "", "tolerances": "", "built_on": ["U.S. and Asia-based application engineering and CAD teams with 25+ years of flexible-circuit design experience", "IPC standards leadership via Mark Finstad, Vice Chair of IPC Flexible Circuit Committees", "485,000 sq ft Zhuhai, China facility producing high-density FPC, rigid-flex, SLP, and flexible heaters", "Full-service EMS from design and prototyping through assembly, test, and box build", "Inventory stocking program supporting just-in-time delivery schedules"], "facts_used": ["Founded in 2000 -> db, /", "Headquarters Minneapolis, Minnesota -> db", "IATF16949 certified -> db", "485,000 sq ft facility in Zhuhai, China -> /", "Products: flexible circuits, rigid-flex, flexible heaters, printed electronics, medical catheters, flat flex cables -> /, /about", "Services: EMS assembly (SMT, through-hole), connector assembly, wire assembly with epoxy coating, plastic molding, sub-assembly, box build -> /about", "Testing services: electrical, functional, hardware, software, custom test equipment -> /about", "Design for manufacturing (DFM) consultation -> /about", "Supply chain management -> /about", "Prototyping through production -> /about", "Low-mix/high-volume and high-mix/low-volume programs -> /about", "Inventory stocking for JIT -> /about", "Industries served: automotive, medical, wearable, industrial, consumer products, telecom/data, CMs, EMS, product development labs -> /about, /", "EV battery monitoring solutions for automotive -> /", "Mark Finstad IPC leadership -> /about", "US/Asia engineering teams with 25+ years experience -> /, /about", "Hybrid business model with US design and Asia manufacturing -> /, /about"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='flexible-circuit-technologies' AND approved AND profile IS NULL;
UPDATE companies SET description='Franklin Precision Industry was established in April 1989 in Franklin, Kentucky. The company took its name from the local community to reflect its focus on manufacturing high‑quality, precision automotive components for distribution across North America and Asia.

The company specializes in fluid control components for automotive fuel and engine systems, producing throttle bodies, EGR valves, fuel pump modules, charcoal canisters, and EV busbars. Production relies on CNC form measurement machines and automated CNC inspection systems that perform repetitive quality checks to reduce human error.

FPI serves the automotive sector, with a noted customer relationship with Aisan Industry Co., Ltd. Its components are supplied to vehicle manufacturers and tier‑one suppliers in both North American and Asian markets.

The business was founded to bring precision‑crafted fluid control parts to the automotive supply chain, emphasizing reliable supply and unmatched quality through certified quality management systems and innovative manufacturing technology.', certifications=ARRAY['IATF16949']::text[], profile='{"capabilities": ["CNC machining", "Automated CNC inspection", "Final product inspection", "Fluid control component manufacturing", "Throttle body production", "EGR valve production", "Fuel pump module assembly", "Charcoal canister production", "EV busbar manufacturing"], "industries": ["Automotive", "Electric Vehicle"], "materials": [], "equipment": ["CNC Form Measurement Machine", "Automated CNC systems"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["IATF 16949 certified quality management system", "Automated CNC inspection for repetitive quality checks", "Specialized in automotive fluid control components", "Serves North American and Asian markets", "Decades of precision manufacturing experience since 1989"], "facts_used": ["Established April 1989 in Franklin, Kentucky -> page:/", "Manufactures automotive fuel and engine system components -> page:/", "Products: throttle bodies, EGR valves, fuel pump modules, charcoal canisters, EV busbars -> page:/", "Uses CNC Form Measurement Machine and automated CNC inspection systems -> page:/", "IATF16949 certified -> db", "Customer: Aisan Industry Co., Ltd. -> db", "Distributes in North America and Asia -> page:/", "Headquarters: Franklin, Kentucky -> db"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='franklin-precision-industry' AND approved AND profile IS NULL;
UPDATE companies SET description='FreshPoint Connecticut operates from a 50,000-square-foot refrigerated warehouse in Hartford, Connecticut. The business traces its roots to 1865 when it was founded as Fowler and Huntting, making it one of the oldest produce distributors in the United States.

The facility maintains nine distinct temperature zones and refrigerated loading docks to preserve an unbroken cold chain. A fleet of more than 60 refrigerated trucks delivers fresh and fresh-cut produce, including organic and value-added tomato items, to customers across the region. The company also offers online ordering through myFreshPoint.com, invoice management via SyscoPay, and dedicated produce specialists who assist with menu planning and market consultation.

Its customer base spans healthcare facilities, educational institutions, hotels and resorts, country clubs, fine-dining and quick-service restaurants, contract feeders, theme parks, cruise lines, and export and wholesale accounts. The distributor also serves business-and-industry dining operations and local, regional, and national chains.

FreshPoint emphasizes a quality assurance program that it describes as the industry''s largest and most comprehensive, covering seed, soil, water sources, sustainability, and worker conditions. Buyers and QA teams conduct field and packing-facility audits, and the Hartford site holds SQF Level 2 certification with a documented HACCP program. Procurement leverage from the combined FreshPoint and Sysco spend, weekly market reports, and a key-drop delivery service are cited as key differentiators.', certifications=ARRAY['FDA COMPLIANT','HACCP','SQF Level 2']::text[], profile='{"capabilities": ["Produce distribution", "Fresh-cut processing (FreshCuts)", "Refrigerated warehousing", "Refrigerated transportation", "Online ordering and invoice management", "Menu planning consultation", "Market reporting and produce alerts", "Key-drop delivery", "Food safety auditing", "Product traceability", "Procurement leverage via Sysco", "Organic produce handling", "Value-added tomato processing", "Grab-and-go produce packaging"], "industries": ["Healthcare", "Export & Wholesale", "Foodservice", "Business in Industry", "Education", "Travel & Leisure", "Hotels", "Resorts", "Country Clubs", "Fine Dining", "Quick Service Restaurants", "Contract Feeders", "Schools", "College and University Dining", "Theme Parks", "Cruise Lines", "Local Chains", "Regional Chains", "National Chains"], "materials": ["Fresh fruits and vegetables", "Fresh-cut produce", "Organic produce", "Tomatoes"], "equipment": ["XRS fleet telemetric system", "Refrigerated loading and receiving docks"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["50,000 sq ft refrigerated warehouse with nine temperature zones", "Fleet of over 60 refrigerated trucks maintaining an unbroken cold chain", "SQF Level 2 certified facility with documented HACCP and recall program", "Traceability of all products direct to the grower", "Key-drop delivery service for consistent timing and early inventory visibility"], "facts_used": ["