UPDATE companies SET description='Heale Manufacturing Co., LLC, was founded in 1957 by H.R. and Dorothy Heale in Waukesha, Wisconsin.

The company specializes in high-mix, low-volume wire harness manufacturing, delivering custom assemblies, prototypes, and short production runs. Its capabilities include cable connectors, shielded leads, and other electrical components, supported by an engineering team that assists with design challenges and manufacturability. Heale maintains a library of over one million drawings, enabling rapid duplication of hard-to-find parts.

Heale serves both military and commercial markets. Its harnesses are used in agriculture, construction, specialty vehicles, and by the U.S. military across numerous defense programs.

Heale emphasizes responsiveness and technical authority as differentiators. It promotes fast RFQ turnaround, personalized service, and ongoing post-delivery support, positioning itself as a partner for projects that larger manufacturers often decline. The founders’ original focus on military-grade quality continues to shape the company’s approach.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Wire harness manufacturing", "Cable connector assembly", "Shielded lead production", "Custom assembly", "Prototyping", "Short-run production", "Engineering design support", "Drawing management", "Post-delivery support"], "industries": ["Agriculture", "Military", "Specialty Vehicles", "Construction"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["High-mix, low-volume production for custom assemblies and prototypes", "Fast RFQ response times", "Engineering support for design and manufacturability", "Library of over 1,000,000 drawings for rapid part duplication", "Personalized service and ongoing post-delivery support"], "facts_used": ["Founded in 1957 by H.R. and Dorothy Heale -> /about", "Headquartered in Waukesha, Wisconsin -> / (contact section)", "ISO 9001:2015 certified -> /about", "Produces wiring harnesses, cable connectors, shielded leads, electrical components -> /about", "Specializes in high-mix, low-volume manufacturing -> / (HEALE DIFFERENCE)", "Maintains library of over 1,000,000 drawings -> / (HEALE DIFFERENCE)", "Serves agriculture, military, specialty vehicles, construction -> / (industries section)", "Family-owned (founders H.R. and Dorothy Heale) -> /about", "Fast RFQ response times -> / (HEALE DIFFERENCE)", "Engineering experience and design support -> / (HEALE DIFFERENCE)", "Personalized service and ongoing support -> / (HEALE DIFFERENCE)", "Company type LLC -> db", "Founded year 1957 -> db", "Headquarters city/state -> db"], "company_type": null, "makes_products": null, "type_evidence": null, "founded_year": null, "employee_count": null, "cage_code": null, "min_order": null, "export_compliance": null, "languages": null, "social_links": null, "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='heale-manufacturing-co' AND approved AND profile IS NULL;
UPDATE companies SET description='HiReli LLC was founded in 2001 in Milford, Delaware, as a women-owned business certified by the Women''s Business Enterprise National Council (WBENC). The company also holds state-level certifications in New Jersey and Delaware and is registered with multiple government agencies.

Operating as a value-added reseller (VAR), HiReli supplies engineered power systems from manufacturers such as Virginia Transformer and Relays & Automation. Its services division provides consulting, education and training, field services and testing, after-market parts sales, and engineering and power system studies. The firm focuses on smart-grid and mission-critical custom power solutions for both public and private sector clients.

HiReli serves utilities, oil and gas, data centers and mission-critical facilities, health care, universities, government, water treatment, telecommunications, transit, renewable energy, distributed energy resources, battery energy storage systems, and distributed generation interconnections. Customers include public agencies and private operators across the U.S. Northeast.

The company emphasizes its engineering and support team, product expertise, and experience as the foundation of its "Highly Reliable Power Systems" tagline. It states that its ISO 9001:2015-certified quality management system underpins a commitment to continuous improvement and consistent delivery.', certifications=ARRAY['ISO 9001:2015','WBENC Women Business Enterprise (WBE)','New Jersey WBE Certification','Delaware WBE Certification']::text[], profile='{"capabilities": ["Custom engineered power systems (smart grid, mission critical)", "Consulting services", "Education and training", "Field services and testing", "After-market parts sales", "Engineering and power system studies", "Value-added resale of electrical equipment"], "industries": ["Utilities", "Oil & Gas", "Data Centers / Mission Critical Facilities", "Health Care", "Universities", "Government", "Water Treatment Systems", "Telecommunications", "Transit", "Renewable Energy", "Distributed Energy Resources", "Battery Energy Storage Systems", "Distributed Generation Interconnections"], "materials": [], "equipment": ["Virginia Transformer Products", "Relays & Automation Products"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Certified Women Business Enterprise (WBE) via WBENC", "ISO 9001:2015 quality management system certification", "Value-added reseller (VAR) with engineering service offerings", "Over 25 years in business (since 2001)", "Partnered solutions with leading power systems manufacturers"], "facts_used": ["Founded 2001 -> db", "Headquarters Milford, Delaware -> db", "WBE certified with WBENC -> /", "State certifications in New Jersey and Delaware -> /", "ISO 9001:2015 certified -> /quality", "Services: consulting, education & training, field services & testing, after-market parts sales, engineering/power system studies -> /services", "Industries served: utilities, oil & gas, data centers, health care, universities, government, water treatment, telecommunications, transit, renewabl